BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='50s';
DO $test$
DECLARE cafe uuid;actor uuid;warehouse uuid;party uuid:='92d1db47-7cc2-4f58-9dbb-61ab51000001';product uuid:='92d1db47-7cc2-4f58-9dbb-61ab51000002';item uuid:='92d1db47-7cc2-4f58-9dbb-61ab51000003';subscription uuid:='92d1db47-7cc2-4f58-9dbb-61ab51000004';future uuid:='92d1db47-7cc2-4f58-9dbb-61ab51000005';draft jsonb;payload jsonb;result jsonb;retry jsonb;detail jsonb;invoice uuid;request uuid:=gen_random_uuid();checks integer:=0;blocked boolean;tax_number text;other_actor uuid;count_before integer;due date:=(now() AT TIME ZONE 'Asia/Riyadh')::date;
BEGIN
 SELECT id,owner_user_id INTO STRICT cafe,actor FROM public.cafes WHERE slug='test-cafe';
 SELECT id INTO STRICT warehouse FROM public.bf_warehouses WHERE cafe_id=cafe AND active ORDER BY id LIMIT 1;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 IF EXISTS(SELECT 1 FROM public.bf_parties WHERE id=party) THEN RAISE EXCEPTION 'REHEARSAL fixture collision';END IF;
 INSERT INTO public.bf_parties(id,cafe_id,name,kind) VALUES(party,cafe,'Recurring rollback customer','customer');
 INSERT INTO public.menu_products(id,cafe_id,name,price) VALUES(product,cafe,'Recurring rollback product',20);
 INSERT INTO public.bf_items(id,cafe_id,name,sku) VALUES(item,cafe,'Recurring rollback item','REC-ROLLBACK-ITEM');
 INSERT INTO public.bf_item_product_links(cafe_id,item_id,product_id,quantity) VALUES(cafe,item,product,2);
 INSERT INTO public.bf_stock(cafe_id,warehouse_id,item_id,quantity,average_cost,value,cost_known) VALUES(cafe,warehouse,item,100,3,300,true);
 SELECT coalesce(nullif(trim(s.tax_number),''),'300000000000003') INTO tax_number FROM public.cafe_settings s WHERE s.cafe_id=cafe;
 draft:=jsonb_build_object('invoice',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('key',0,'productId',product,'quantity',2,'price',20,'vatRate',15)),'warehouseId',warehouse,'partyId',party,'accountId','','paymentKind','credit','discountValue',0,'discountKind','amount','vatRate',15,'taxInclusive',false,'note','Recurring rollback'),
 'issuer',jsonb_build_object('name','Recurring rollback seller','vatNumber',coalesce(tax_number,'300000000000003'),'address','Rollback seller Riyadh address'),'template','standard','deliveryMethod','print','deposit',jsonb_build_object('kind','amount','value',0,'paid',false),'shipping','none','delivery',jsonb_build_object('confirmed',false,'date',''),'attachments','[]'::jsonb,'extraFields','[]'::jsonb);
 payload:=jsonb_build_object('name','Recurring rollback subscription','firstDate',due,'unit','month','interval',1,'count',2,'leadDays',0,'paymentTermsDays',14,'showPeriod',true,'active',true,'document',draft);
 SELECT count(*) INTO count_before FROM public.bf_documents WHERE cafe_id=cafe;
 result:=public.brand_finance_save_recurring_invoice(cafe,subscription,0,payload);
 IF (result->>'total')::numeric<>46 OR (result->>'tax')::numeric<>6 OR (result->>'generatedCount')::integer<>0 THEN RAISE EXCEPTION 'REHEARSAL canonical preview totals';END IF;checks:=checks+1;
 IF (SELECT count(*) FROM public.bf_documents WHERE cafe_id=cafe)<>count_before OR (SELECT quantity FROM public.bf_stock WHERE cafe_id=cafe AND item_id=item AND warehouse_id=warehouse)<>100 THEN RAISE EXCEPTION 'REHEARSAL save posted financial or stock';END IF;checks:=checks+1;
 retry:=public.brand_finance_save_recurring_invoice(cafe,subscription,0,payload);IF retry<>result THEN RAISE EXCEPTION 'REHEARSAL save idempotence';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub','',true);
 result:=brand_finance_private.recurring_worker();
 IF (result->>'issued')::integer<>1 OR (result->>'failed')::integer<>0 THEN RAISE EXCEPTION 'REHEARSAL worker did not issue: % / %',result,(SELECT last_error FROM public.bf_recurring_invoices WHERE id=subscription);END IF;checks:=checks+1;
 SELECT document_id INTO STRICT invoice FROM public.bf_recurring_occurrences WHERE subscription_id=subscription;
 IF (SELECT created_by FROM public.bf_documents WHERE id=invoice)<>actor OR (SELECT paid FROM public.bf_documents WHERE id=invoice)<>0 THEN RAISE EXCEPTION 'REHEARSAL actor or payment mismatch';END IF;checks:=checks+1;
 IF (SELECT quantity FROM public.bf_stock WHERE cafe_id=cafe AND item_id=item AND warehouse_id=warehouse)<>96 OR (SELECT sum(debit-credit) FROM public.bf_journal WHERE document_id=invoice)<>0 THEN RAISE EXCEPTION 'REHEARSAL stock or journal mismatch';END IF;checks:=checks+1;
 IF (SELECT count(*) FROM public.bf_company_invoices WHERE document_id=invoice)<>1 THEN RAISE EXCEPTION 'REHEARSAL canonical snapshot missing';END IF;checks:=checks+1;
 result:=brand_finance_private.recurring_worker();IF (result->>'issued')::integer<>0 OR (SELECT count(*) FROM public.bf_recurring_occurrences WHERE subscription_id=subscription)<>1 THEN RAISE EXCEPTION 'REHEARSAL duplicate worker';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 detail:=public.brand_finance_recurring_invoices(cafe,subscription);
 IF (detail->>'historyTotal')::integer<>1 OR jsonb_array_length(detail->'invoices')<>1 OR detail#>>'{invoices,0,dueDate}'<>(due+14)::text OR (detail#>>'{invoices,0,invoiceId}')::uuid<>invoice THEN RAISE EXCEPTION 'REHEARSAL invoice lineage';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.brand_finance_save_recurring_invoice(cafe,subscription,(detail->>'revision')::integer,jsonb_set(payload,'{interval}','2'));EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL cadence edit after issue';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.brand_finance_transition_recurring_invoice(cafe,subscription,(detail->>'revision')::integer,'delete',gen_random_uuid());EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL delete issued history';END IF;checks:=checks+1;
 result:=public.brand_finance_transition_recurring_invoice(cafe,subscription,(detail->>'revision')::integer,'pause',request);
 retry:=public.brand_finance_transition_recurring_invoice(cafe,subscription,(detail->>'revision')::integer,'pause',request);IF retry<>result THEN RAISE EXCEPTION 'REHEARSAL transition idempotence';END IF;checks:=checks+1;
 IF (SELECT status FROM public.bf_recurring_invoices WHERE id=subscription)<>'paused' THEN RAISE EXCEPTION 'REHEARSAL pause';END IF;checks:=checks+1;
 detail:=public.brand_finance_recurring_invoices(cafe,subscription);
 result:=public.brand_finance_transition_recurring_invoice(cafe,subscription,(detail->>'revision')::integer,'resume',gen_random_uuid());IF result->>'status'<>'active' THEN RAISE EXCEPTION 'REHEARSAL resume';END IF;checks:=checks+1;
 payload:=jsonb_set(jsonb_set(payload,'{firstDate}',to_jsonb((due+5)::text)),'{count}','1');
 result:=public.brand_finance_save_recurring_invoice(cafe,future,0,payload);
 request:=gen_random_uuid();result:=public.brand_finance_transition_recurring_invoice(cafe,future,1,'run',request);IF result->>'status'<>'not_due' THEN RAISE EXCEPTION 'REHEARSAL early issue';END IF;checks:=checks+1;
 IF EXISTS(SELECT 1 FROM public.bf_requests WHERE cafe_id=cafe AND request_id=request) THEN RAISE EXCEPTION 'REHEARSAL not-due run cached';END IF;checks:=checks+1;
 result:=public.brand_finance_transition_recurring_invoice(cafe,future,1,'delete',gen_random_uuid());IF result->>'status'<>'deleted' OR public.brand_finance_recurring_invoices(cafe,future) IS NOT NULL THEN RAISE EXCEPTION 'REHEARSAL delete unissued';END IF;checks:=checks+1;
 IF brand_finance_private.recurring_date('2027-01-31','month',1,1)<>'2027-02-28' OR brand_finance_private.recurring_date('2027-01-31','month',1,2)<>'2027-03-31' OR brand_finance_private.recurring_date('2024-02-29','year',1,4)<>'2028-02-29' OR brand_finance_private.recurring_date('2024-02-29','year',1,1)<>'2025-02-28' OR brand_finance_private.recurring_date('2026-12-28','week',1,1)<>'2027-01-04' THEN RAISE EXCEPTION 'REHEARSAL date anchors';END IF;checks:=checks+5;
 result:=public.brand_finance_recurring_invoices(cafe,NULL,jsonb_build_object('partyId',party,'limit',1));IF (result->>'total')::integer<>1 OR jsonb_array_length(result->'items')<>1 OR result#>'{items,0,payload}' IS NOT NULL THEN RAISE EXCEPTION 'REHEARSAL compact list';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.brand_finance_save_recurring_invoice(cafe,gen_random_uuid(),0,jsonb_set(payload,'{document,invoice,paymentKind}','"cash"'));EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL automatic collection accepted';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub','',true);blocked:=false;BEGIN PERFORM public.brand_finance_recurring_invoices(cafe,subscription);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL anonymous access';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);blocked:=false;BEGIN PERFORM public.brand_finance_recurring_invoices('92d1db47-7cc2-4f58-9dbb-61ab51000099',subscription);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL cross tenant access';END IF;checks:=checks+1;
 IF has_function_privilege('authenticated','brand_finance_private.recurring_worker()','EXECUTE') OR has_function_privilege('authenticated','brand_finance_private.issue_company_invoice_actor(uuid,boolean,uuid,uuid,integer,numeric,uuid,text)','EXECUTE') OR has_table_privilege('authenticated','public.bf_recurring_invoices','INSERT') OR has_function_privilege('anon','public.brand_finance_save_recurring_invoice(uuid,uuid,integer,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'REHEARSAL direct privilege exposure';END IF;checks:=checks+1;
 IF (SELECT count(*) FROM cron.job WHERE jobname='branda-recurring-invoices' AND active)<>1 THEN RAISE EXCEPTION 'REHEARSAL cron missing';END IF;checks:=checks+1;
 SET CONSTRAINTS ALL IMMEDIATE;
 PERFORM set_config('branda.recurring_rehearsal',jsonb_build_object('ok',true,'checks',checks,'partyId',party,'productId',product,'scope','rollback transaction only')::text,true);
END $test$;
DO $more$
DECLARE cafe uuid;actor uuid;other_actor uuid;subscription uuid:='92d1db47-7cc2-4f58-9dbb-61ab51000004';test_id uuid:=gen_random_uuid();draft_id uuid:=gen_random_uuid();request_id uuid:=gen_random_uuid();payload jsonb;doc jsonb;result jsonb;detail jsonb;before_count integer;checks integer:=0;blocked boolean;invoice uuid;due date:=(now() AT TIME ZONE 'Asia/Riyadh')::date;
BEGIN
 SET CONSTRAINTS ALL DEFERRED;
 SELECT id,owner_user_id INTO STRICT cafe,actor FROM public.cafes WHERE slug='test-cafe';
 SELECT s.payload INTO payload FROM public.bf_recurring_invoices s WHERE s.id=subscription;
 doc:=jsonb_set(payload->'document','{supplyDate}',to_jsonb(due::text));
 result:=public.brand_finance_save_invoice_draft(cafe,draft_id,0,doc);
 result:=public.brand_finance_issue_company_invoice(cafe,draft_id,1,46);
 invoice:=(result->>'id')::uuid;
 IF (result->>'total')::numeric<>46 OR (SELECT created_by FROM public.bf_documents WHERE id=invoice)<>actor OR (SELECT sum(debit-credit) FROM public.bf_journal WHERE document_id=invoice)<>0 THEN RAISE EXCEPTION 'REHEARSAL existing manual issuer regression';END IF;checks:=checks+1;
 IF public.brand_finance_issue_company_invoice(cafe,draft_id,1,46)<>result THEN RAISE EXCEPTION 'REHEARSAL manual issuer duplicate';END IF;checks:=checks+1;
 SELECT p.id INTO other_actor FROM public.profiles p WHERE p.status='active' AND p.id<>actor AND NOT EXISTS(SELECT 1 FROM public.bf_staff st WHERE st.cafe_id=cafe AND st.user_id=p.id) LIMIT 1;
 IF other_actor IS NULL THEN RAISE EXCEPTION 'REHEARSAL no actor fixture';END IF;
 INSERT INTO public.bf_staff(cafe_id,user_id,name,role) VALUES(cafe,other_actor,'Recurring rollback actor','manager');
 PERFORM set_config('request.jwt.claim.sub',other_actor::text,true);
 payload:=jsonb_set(jsonb_set(jsonb_set(payload,'{count}','1'),'{firstDate}',to_jsonb((due+5)::text)),'{leadDays}','5');
 result:=public.brand_finance_save_recurring_invoice(cafe,test_id,0,payload);
 IF result->>'nextIssueDate'<>due::text THEN RAISE EXCEPTION 'REHEARSAL lead days';END IF;checks:=checks+1;
 UPDATE public.bf_staff SET active=false WHERE cafe_id=cafe AND user_id=other_actor;
 PERFORM set_config('request.jwt.claim.sub','',true);
 SELECT count(*) INTO before_count FROM public.bf_documents WHERE cafe_id=cafe;
 result:=brand_finance_private.recurring_worker();
 IF (result->>'failed')::integer<>1 OR (result->>'issued')::integer<>0 OR (SELECT generated_count FROM public.bf_recurring_invoices WHERE id=test_id)<>0 OR (SELECT count(*) FROM public.bf_documents WHERE cafe_id=cafe)<>before_count THEN RAISE EXCEPTION 'REHEARSAL revoked actor issued invoice';END IF;checks:=checks+1;
 IF NOT EXISTS(SELECT 1 FROM public.bf_recurring_invoices WHERE id=test_id AND failure_count=1 AND last_error IS NOT NULL AND next_attempt_at>now()) THEN RAISE EXCEPTION 'REHEARSAL failed backoff';END IF;checks:=checks+1;
 IF NOT EXISTS(SELECT 1 FROM public.bf_recurring_events WHERE subscription_id=test_id AND action='failed') THEN RAISE EXCEPTION 'REHEARSAL failed audit missing';END IF;checks:=checks+1;
 result:=brand_finance_private.recurring_worker();IF (result->>'failed')::integer<>0 THEN RAISE EXCEPTION 'REHEARSAL backoff ignored';END IF;checks:=checks+1;
 UPDATE public.bf_staff SET active=true WHERE cafe_id=cafe AND user_id=other_actor;
 UPDATE public.bf_recurring_invoices SET next_attempt_at=now() WHERE id=test_id;
 result:=brand_finance_private.recurring_worker();
 IF (result->>'issued')::integer<>1 OR (SELECT status FROM public.bf_recurring_invoices WHERE id=test_id)<>'completed' OR (SELECT next_date FROM public.bf_recurring_invoices WHERE id=test_id) IS NOT NULL THEN RAISE EXCEPTION 'REHEARSAL finite schedule completion';END IF;checks:=checks+1;
 SELECT document_id INTO invoice FROM public.bf_recurring_occurrences WHERE subscription_id=test_id;
 IF (SELECT created_by FROM public.bf_documents WHERE id=invoice)<>other_actor OR (SELECT paid FROM public.bf_documents WHERE id=invoice)<>0 THEN RAISE EXCEPTION 'REHEARSAL saved actor attribution';END IF;checks:=checks+1;
 IF (SELECT snapshot->>'supplyDate' FROM public.bf_company_invoices WHERE document_id=invoice)<>due::text OR (SELECT due_date FROM public.bf_recurring_occurrences WHERE subscription_id=test_id)<>due+19 THEN RAISE EXCEPTION 'REHEARSAL early issue dates';END IF;checks:=checks+1;
 result:=brand_finance_private.recurring_worker();IF (result->>'issued')::integer<>0 THEN RAISE EXCEPTION 'REHEARSAL finite schedule overrun';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 detail:=public.brand_finance_recurring_invoices(cafe,test_id);
 IF jsonb_array_length(detail->'upcoming')<>0 OR jsonb_array_length(detail->'invoices')<>1 THEN RAISE EXCEPTION 'REHEARSAL completed preview';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.brand_finance_transition_recurring_invoice(cafe,test_id,(detail->>'revision')::integer,'resume',gen_random_uuid());EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL completed resume';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.brand_finance_transition_recurring_invoice(cafe,test_id,999,'run',gen_random_uuid());EXCEPTION WHEN serialization_failure THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL stale revision';END IF;checks:=checks+1;
 UPDATE public.bf_staff SET role='warehouse' WHERE cafe_id=cafe AND user_id=other_actor;
 PERFORM set_config('request.jwt.claim.sub',other_actor::text,true);
 blocked:=false;BEGIN PERFORM public.brand_finance_save_recurring_invoice(cafe,gen_random_uuid(),0,payload);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL warehouse subscription write';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.brand_finance_recurring_invoices(cafe,test_id);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL warehouse financial read';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 blocked:=false;BEGIN PERFORM public.brand_finance_save_recurring_invoice(cafe,gen_random_uuid(),0,jsonb_set(jsonb_set(jsonb_set(payload,'{unit}','"year"'),'{interval}','365'),'{count}','10000'));EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL calendar overflow accepted';END IF;checks:=checks+1;
 IF has_schema_privilege('authenticated','cron','USAGE') OR has_schema_privilege('anon','cron','USAGE') OR has_schema_privilege('service_role','cron','USAGE') THEN RAISE EXCEPTION 'REHEARSAL cron exposed';END IF;checks:=checks+1;
 SET LOCAL ROLE authenticated;
 blocked:=false;BEGIN PERFORM cron.schedule('recurring-forbidden-test','* * * * *','SELECT 1');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 SET LOCAL ROLE postgres;
 IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL authenticated cron invocation';END IF;checks:=checks+1;
 IF (SELECT count(*) FROM public.bf_recurring_occurrences WHERE subscription_id=test_id)<>1 THEN RAISE EXCEPTION 'REHEARSAL final uniqueness';END IF;checks:=checks+1;
 SET CONSTRAINTS ALL IMMEDIATE;
 PERFORM set_config('branda.recurring_rehearsal',(current_setting('branda.recurring_rehearsal')::jsonb||jsonb_build_object('checks',(current_setting('branda.recurring_rehearsal')::jsonb->>'checks')::integer+checks))::text,true);
END $more$;
DO $draft_cap$
DECLARE cafe uuid;actor uuid;doc jsonb;open_count integer;id1 uuid:=gen_random_uuid();id2 uuid:=gen_random_uuid();blocked boolean;checks integer:=0;
BEGIN
 SELECT id,owner_user_id INTO STRICT cafe,actor FROM public.cafes WHERE slug='test-cafe';
 SELECT payload->'document' INTO doc FROM public.bf_recurring_invoices WHERE id='92d1db47-7cc2-4f58-9dbb-61ab51000004';
 SELECT count(*) INTO open_count FROM public.bf_invoice_drafts d WHERE d.cafe_id=cafe AND NOT EXISTS(SELECT 1 FROM public.bf_company_invoices i WHERE i.cafe_id=d.cafe_id AND i.draft_id=d.id);
 IF open_count>499 THEN RAISE EXCEPTION 'REHEARSAL existing open drafts exceed fixture capacity';END IF;
 INSERT INTO public.bf_invoice_drafts(id,cafe_id,payload,created_by,updated_by) SELECT gen_random_uuid(),cafe,doc,actor,actor FROM generate_series(1,499-open_count);
 PERFORM public.brand_finance_save_invoice_draft(cafe,id1,0,doc);
 IF NOT EXISTS(SELECT 1 FROM public.bf_invoice_drafts WHERE id=id1) THEN RAISE EXCEPTION 'REHEARSAL issued drafts consumed open-draft cap';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.brand_finance_save_invoice_draft(cafe,id2,0,doc);EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL open-draft cap bypass';END IF;checks:=checks+1;
 PERFORM set_config('branda.recurring_rehearsal',(current_setting('branda.recurring_rehearsal')::jsonb||jsonb_build_object('checks',(current_setting('branda.recurring_rehearsal')::jsonb->>'checks')::integer+checks))::text,true);
END $draft_cap$;
DO $batch$
DECLARE cafe uuid;actor uuid;payload jsonb;result jsonb;idx integer;count_before integer;checks integer:=0;
BEGIN
 SET CONSTRAINTS ALL DEFERRED;
 SELECT id,owner_user_id INTO STRICT cafe,actor FROM public.cafes WHERE slug='test-cafe';
 SELECT jsonb_set(jsonb_set(s.payload,'{count}','1'),'{firstDate}',to_jsonb((now() AT TIME ZONE 'Asia/Riyadh')::date::text)) INTO payload FROM public.bf_recurring_invoices s WHERE s.id='92d1db47-7cc2-4f58-9dbb-61ab51000004';
 FOR idx IN 1..11 LOOP PERFORM public.brand_finance_save_recurring_invoice(cafe,gen_random_uuid(),0,payload);END LOOP;
 SELECT count(*) INTO count_before FROM public.bf_documents WHERE cafe_id=cafe;
 PERFORM set_config('request.jwt.claim.sub','',true);
 result:=brand_finance_private.recurring_worker();IF (result->>'issued')::integer<>10 OR (SELECT count(*) FROM public.bf_documents WHERE cafe_id=cafe)<>count_before+10 THEN RAISE EXCEPTION 'REHEARSAL worker batch not bounded';END IF;checks:=checks+1;
 result:=brand_finance_private.recurring_worker();IF (result->>'issued')::integer<>1 THEN RAISE EXCEPTION 'REHEARSAL worker backlog skipped';END IF;checks:=checks+1;
 result:=brand_finance_private.recurring_worker();IF (result->>'issued')::integer<>0 THEN RAISE EXCEPTION 'REHEARSAL batch repeated invoices';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 SET CONSTRAINTS ALL IMMEDIATE;
 PERFORM set_config('branda.recurring_rehearsal',(current_setting('branda.recurring_rehearsal')::jsonb||jsonb_build_object('checks',(current_setting('branda.recurring_rehearsal')::jsonb->>'checks')::integer+checks))::text,true);
END $batch$;
SELECT current_setting('branda.recurring_rehearsal')::jsonb AS verification;

ROLLBACK;
